import { readFileSync } from "node:fs";
import {
  SP_PI_TRAJECTORY_FORMAT, nativeTrajectoryEntrySchema, sha256Hex,
  type JsonValue, type NativeTrajectoryEntry,
} from "@eval-platform/eval-contracts";

import type { EvidenceBlobStore } from "./evidence.js";
import type { ExportedEvidence, ExportedTrajectoryRecord } from "./model.js";

/** Real, safe native Pi records generated by the published public UA helpers.
 * Only test Chat/Submission identity is rebound; production never reads this file. */
const publicFixture = JSON.parse(readFileSync(new URL("../../../../fixtures/pi-native-public-v1.json", import.meta.url), "utf8")) as {
  readonly records: readonly NativeTrajectoryEntry[];
};

function object(value: unknown): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) throw new Error("Expected Pi fixture object");
  return value as Record<string, unknown>;
}

export function publicNativeRecords(
  ingestSeqs: readonly number[], scope: { readonly chatId: string; readonly submissionId: string },
): NativeTrajectoryEntry[] {
  return ingestSeqs.map((seq) => {
    const found = publicFixture.records.find((entry) => entry.ingestSeq === seq);
    if (!found) throw new Error(`No public Pi fixture record ${seq}`);
    const entry = structuredClone(found);
    const record = object(entry.record);
    object(record.resource).sessionId = scope.chatId;
    record.submissionId = scope.submissionId;
    const value = object(object(record.record).value);
    if (value.kind === "springbrand.trajectory" && object(value.data).type === "event") {
      const event = object(object(value.data).event);
      object(event.resource).sessionId = scope.chatId;
      event.submissionId = scope.submissionId;
    }
    return nativeTrajectoryEntrySchema.parse(entry);
  });
}

/** A targeted oversized-body variant of the generated safe Pi assistant. */
export function publicAssistantRecord(
  ingestSeq: number, scope: { readonly chatId: string; readonly submissionId: string }, text: string,
): NativeTrajectoryEntry {
  const source = publicNativeRecords([14], scope)[0]!;
  const value = object(object(source.record.record).value);
  value.id = ingestSeq;
  const message = object((value.model as unknown[])[0]);
  message.content = [{ type: "text", text }];
  return nativeTrajectoryEntrySchema.parse({ ...source, ingestSeq });
}

/** Test-only blob store; not exported from the package. */
export function createMemoryEvidenceBlobs(): EvidenceBlobStore & {
  readonly blobs: Map<string, Uint8Array>;
  readonly manifests: Map<string, Uint8Array>;
} {
  const blobs = new Map<string, Uint8Array>();
  const manifests = new Map<string, Uint8Array>();
  return {
    blobs,
    manifests,
    async putBlob(content, maxBytes) {
      const bytes = new Uint8Array(await new Response(content).arrayBuffer());
      if (bytes.byteLength > maxBytes) throw new Error("Evidence blob is too large");
      const sha256 = await sha256Hex(bytes);
      if (!blobs.has(sha256)) blobs.set(sha256, bytes);
      return { sha256, size: bytes.byteLength };
    },
    async readBlob(sha256) {
      const bytes = blobs.get(sha256);
      return bytes === undefined ? undefined : new Response(new Uint8Array(bytes)).body!;
    },
    async putManifest(evidenceHex, bytes) {
      if (!manifests.has(evidenceHex)) manifests.set(evidenceHex, bytes);
    },
    async readManifest(evidenceHex) {
      return manifests.get(evidenceHex);
    },
  };
}

export function exportedEvidence(input: {
  readonly samplingId: string;
  readonly chatId?: string;
  readonly submissionId?: string;
  readonly files?: Readonly<Record<string, string>>;
  /** Test-only native `{ingestSeq,record}` rows; ingestSeq is the source cursor, not an array position. */
  readonly events?: readonly (JsonValue | NativeTrajectoryEntry)[];
}): ExportedEvidence {
  const files = input.files ?? { "/index.html": "<h1>Hello</h1>" };
  const events = input.events ?? publicNativeRecords([1], {
    chatId: input.chatId ?? "chat-1", submissionId: input.submissionId ?? "submission-1",
  });
  const encoder = new TextEncoder();
  return {
    source: { framework: "sp", samplingId: input.samplingId, agentRef: { chatId: input.chatId ?? "chat-1" } },
    artifacts: Object.entries(files).map(([path, content]) => ({
      path, size: encoder.encode(content).byteLength, mediaType: "text/html",
    })),
    omitted: [],
    subjectInputs: [],
    async readFile(path) {
      const content = files[path];
      if (content === undefined) throw new Error(`No exported file ${path}`);
      return new Response(content).body!;
    },
    async* readTrajectory(afterSeq, frozenThroughSeq) {
      const seqOf = (record: JsonValue | NativeTrajectoryEntry, index: number): number => {
        if (record === null || typeof record !== "object" || Array.isArray(record)) return index + 1;
        const seq = (record as { readonly ingestSeq?: unknown }).ingestSeq;
        return typeof seq === "number" ? seq : index + 1;
      };
      const throughSeq = frozenThroughSeq ?? (events.at(-1) === undefined ? 0 : seqOf(events.at(-1)!, events.length - 1));
      const records: ExportedTrajectoryRecord[] = [];
      for (const [index, record] of events.entries()) {
        const seq = seqOf(record, index);
        if (seq > afterSeq && seq <= throughSeq) {
          const raw = encoder.encode(`${JSON.stringify(record)}\n`);
          records.push({ seq, byteLength: raw.byteLength,
            readJsonl: async () => new Response(raw).body! });
        }
      }
      yield { throughSeq, records, nextAfterSeq: null };
    },
    trajectoryFormat: SP_PI_TRAJECTORY_FORMAT,
    trajectoryComplete: true,
  };
}

/** A test clock; `tickMs` advances it on every read, so a value that must stay stable has to be persisted. */
export function testClock(start = "2026-10-15T00:00:00.000Z", tickMs = 0) {
  let time = Date.parse(start);
  return {
    now: (): string => {
      const current = new Date(time).toISOString();
      time += tickMs;
      return current;
    },
    advance: (milliseconds: number): void => { time += milliseconds; },
  };
}
